const JPEG_PREFIX = 'data:image/jpeg;base64,';
const MAX_IMAGE_LENGTH = 650_000;
const MAX_BODY_LENGTH = MAX_IMAGE_LENGTH + 10_000;
const CATEGORIES = new Set(['stray', 'pet', 'cafe', 'community']);
const GENDERS = new Set(['female', 'male', 'unknown']);
const GALLERY_PAGE_SIZE = 100;
const SAMPLE_CATS = new Map([
  ['mochi', { name: 'Mochi', observed: '2026-11-16' }],
  ['pudding', { name: 'Pudding', observed: '2026-11-14' }],
  ['shadow', { name: 'Shadow', observed: '2026-11-12' }],
  ['biscuit', { name: 'Biscuit', observed: '2026-11-10' }],
]);
const SIGHTING_FIELDS = 'id, name, category, city, location, lat, lng, note, observed, status, age_months AS ageMonths, gender, created_at AS createdAt';
const AUTH_PATHS = new Set(['/api/auth/register', '/api/auth/login', '/api/auth/reset', '/api/auth/logout']);
const AUTH_COOKIE = '__Host-manameow_session';
const AUTH_SESSION_SECONDS = 30 * 24 * 60 * 60;
const AUTH_RATE_WINDOW = 15 * 60;
const AUTH_PASSWORD_SCHEME = 'pbkdf2-sha256-hmac-sha256-v1';
// Hosted Workers reject higher iteration counts.
const AUTH_PASSWORD_ITERATIONS = 100_000;
const AUTH_EMAIL_LIMITS = { register: 5, login: 12, reset: 8 };
const AUTH_ENCODER = new TextEncoder();

class RequestError extends Error {
  constructor(status, code, message, headers) {
    super(message);
    this.status = status;
    this.code = code;
    this.headers = headers;
  }
}

function json(data, status = 200, headers) {
  return Response.json(data, { status, headers: { 'Cache-Control': 'no-store', ...headers } });
}

function getAccount(request, env) {
  const id = request.headers.get('oai-authenticated-user-id');
  const email = request.headers.get('oai-authenticated-user-email');
  const moderatorEmail = env.MODERATOR_EMAIL?.trim().toLowerCase();
  const moderatorId = env.MODERATOR_ACCOUNT_ID?.trim();
  return {
    id: id && email ? id : null,
    moderator: Boolean(id && (id === moderatorId || (email && moderatorEmail && email.toLowerCase() === moderatorEmail))),
  };
}

function requireAccount(account) {
  if (!account.id) throw new RequestError(401, 'sign_in_required', 'Sign in to continue.');
}

function requireModerator(account) {
  requireAccount(account);
  if (!account.moderator) throw new RequestError(403, 'forbidden', 'Moderator access is required.');
}

function requireSameOrigin(request, url) {
  if (request.headers.get('Origin') !== url.origin) {
    throw new RequestError(403, 'invalid_origin', 'Submit from the ManaMeow website.');
  }
}

async function readJson(request, maxLength = MAX_BODY_LENGTH) {
  if (!/^application\/json(?:;|$)/i.test(request.headers.get('Content-Type') || '')) {
    throw new RequestError(415, 'expected_json', 'Send the details as JSON.');
  }
  const rejectSize = () => maxLength === MAX_BODY_LENGTH
    ? new RequestError(413, 'photo_too_large', 'Choose a smaller photo.')
    : new RequestError(413, 'request_too_large', 'The request is too large.');
  if (!request.body || Number(request.headers.get('Content-Length')) > maxLength) {
    throw rejectSize();
  }
  const reader = request.body.getReader();
  const decoder = new TextDecoder();
  let length = 0;
  let body = '';
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      length += value.length;
      if (length > maxLength) {
        await reader.cancel();
        throw rejectSize();
      }
      body += decoder.decode(value, { stream: true });
    }
  } finally {
    reader.releaseLock();
  }
  try {
    const data = JSON.parse(body + decoder.decode());
    if (data && typeof data === 'object' && !Array.isArray(data)) return data;
  } catch {
    // All invalid JSON is returned as the same client error.
  }
  throw new RequestError(400, 'invalid_json', 'Send a valid JSON object.');
}

function sessionToken(request) {
  const cookie = request.headers.get('Cookie') ?? '';
  const prefix = AUTH_COOKIE + '=';
  for (const value of cookie.split(';')) {
    const parameter = value.trim();
    if (parameter.startsWith(prefix)) {
      const token = parameter.slice(prefix.length);
      return /^[a-f0-9]{64}$/.test(token) ? token : null;
    }
  }
  return null;
}

function authHex(bytes) {
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

function authRandom(bytes) {
  return authHex(crypto.getRandomValues(new Uint8Array(bytes)));
}

async function authDigest(value) {
  return authHex(new Uint8Array(await crypto.subtle.digest('SHA-256', AUTH_ENCODER.encode(value))));
}

async function getRequestAccount(request, env) {
  const account = getAccount(request, env);
  const token = sessionToken(request);
  const platform = { ...account, local: false, platformModerator: account.moderator };
  if (!token || !env.DB) return platform;
  const local = await env.DB.prepare(
    'SELECT a.id, a.email FROM local_sessions s JOIN local_accounts a ON a.id = s.account_id ' +
    'WHERE s.token_hash = ? AND s.expires_at > ? AND s.credential_version = a.credential_version',
  ).bind(await authDigest(token), Math.floor(Date.now() / 1000)).first();
  if (!local) return platform;
  return { id: 'local:' + local.id, email: local.email, local: true, moderator: false, platformModerator: platform.moderator };
}

function authEmail(input) {
  const email = typeof input === 'string' && input.length <= 320 ? input.trim().toLowerCase() : '';
  const [name, domain, extra] = email.split('@');
  if (email.length > 254 || !name || name.length > 64 || !domain || extra !== undefined ||
      !/^[a-z0-9.!#$%&'*+/=?^_\x60{|}~-]+$/.test(name) || name.startsWith('.') || name.endsWith('.') || name.includes('..') ||
      !domain.includes('.') || domain.split('.').some((label) => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))) {
    throw new RequestError(400, 'invalid_email', 'Enter a valid email address.');
  }
  return email;
}

function authPassword(input) {
  if (typeof input === 'string' && input.length <= 256 && !/[\uD800-\uDFFF]/u.test(input)) {
    const password = input.normalize('NFC');
    const length = [...password].length;
    if (length >= 10 && length <= 128) return password;
  }
  throw new RequestError(400, 'invalid_password', 'Use a password with 10 to 128 characters.');
}

async function authPepper(env) {
  const pepper = env.MANAMEOW_AUTH_PEPPER;
  if (typeof pepper !== 'string' || AUTH_ENCODER.encode(pepper).length < 32) {
    throw new RequestError(503, 'auth_unavailable', 'Email sign-in is temporarily unavailable.');
  }
  return crypto.subtle.importKey('raw', AUTH_ENCODER.encode(pepper), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
}

async function authMac(key, value) {
  return new Uint8Array(await crypto.subtle.sign('HMAC', key, AUTH_ENCODER.encode(value)));
}

async function passwordDigest(password, salt, iterations, pepper) {
  const protectedPassword = await authMac(pepper, 'password\0' + password);
  const key = await crypto.subtle.importKey('raw', protectedPassword, 'PBKDF2', false, ['deriveBits']);
  const saltBytes = Uint8Array.from(salt.match(/../g), (byte) => parseInt(byte, 16));
  const hash = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: saltBytes, iterations }, key, 256);
  return authHex(new Uint8Array(hash));
}

function equalDigests(first, second) {
  if (typeof first !== 'string' || typeof second !== 'string' || first.length !== second.length) return false;
  if (typeof crypto.subtle.timingSafeEqual === 'function') {
    return crypto.subtle.timingSafeEqual(AUTH_ENCODER.encode(first), AUTH_ENCODER.encode(second));
  }
  let difference = 0;
  for (let index = 0; index < first.length; index++) {
    difference |= first.charCodeAt(index) ^ second.charCodeAt(index);
  }
  return difference === 0;
}

async function newCredentials(password, pepper) {
  const salt = authRandom(16);
  const recovery = authRandom(16);
  const [hash, recoveryHash] = await Promise.all([
    passwordDigest(password, salt, AUTH_PASSWORD_ITERATIONS, pepper),
    authDigest(recovery),
  ]);
  return { salt, hash, recoveryHash, recoveryCode: recovery.toUpperCase().match(/.{8}/g).join('-') };
}

async function authRateLimit(request, db, action, email, pepper, now) {
  const ip = request.headers.get('CF-Connecting-IP') ?? '';
  const source = /^[a-f0-9:.]{3,45}$/i.test(ip) ? ip.toLowerCase() : 'unknown';
  const [sourceKey, emailKey] = await Promise.all([
    authMac(pepper, 'rate-source\0' + action + '\0' + source),
    authMac(pepper, 'rate-email\0' + action + '\0' + email),
  ]);
  const statement = 'INSERT INTO local_auth_limits (bucket, attempts, expires_at) VALUES (?, 1, ?) ' +
    'ON CONFLICT(bucket) DO UPDATE SET ' +
    'attempts = CASE WHEN expires_at <= ? THEN 1 ELSE MIN(attempts + 1, ?) END, ' +
    'expires_at = CASE WHEN expires_at <= ? THEN excluded.expires_at ELSE expires_at END ' +
    'RETURNING attempts, expires_at';
  const consume = (key, limit) => db.prepare(statement).bind(authHex(key), now + AUTH_RATE_WINDOW, now, limit + 1, now).first();
  const sourceLimit = source === 'unknown' ? 240 : 80;
  const fromSource = await consume(sourceKey, sourceLimit);
  const emailLimit = AUTH_EMAIL_LIMITS[action];
  const byEmail = fromSource.attempts > sourceLimit ? null : await consume(emailKey, emailLimit);
  const expiry = byEmail === null ? fromSource.expires_at : byEmail.attempts > emailLimit ? byEmail.expires_at : null;
  if (expiry !== null) {
    throw new RequestError(429, 'rate_limited', 'Too many attempts. Try again later.', { 'Retry-After': String(expiry - now) });
  }
  if (crypto.getRandomValues(new Uint8Array(1))[0] < 8) {
    await db.batch([
      db.prepare('DELETE FROM local_auth_limits WHERE expires_at <= ?').bind(now),
      db.prepare('DELETE FROM local_sessions WHERE expires_at <= ?').bind(now),
    ]);
  }
}

async function newLocalSession(now) {
  const token = authRandom(32);
  return { token, hash: await authDigest(token), expiresAt: now + AUTH_SESSION_SECONDS };
}

function sessionInsert(db, accountId, version, session) {
  return db.prepare(
    'INSERT INTO local_sessions (token_hash, account_id, credential_version, expires_at) ' +
    'SELECT ?, id, credential_version, ? FROM local_accounts WHERE id = ? AND credential_version = ?',
  ).bind(session.hash, session.expiresAt, accountId, version);
}

function authSessionCookie(token, seconds) {
  return AUTH_COOKIE + '=' + token + '; Max-Age=' + seconds + '; Path=/; HttpOnly; Secure; SameSite=Lax';
}

function invalidLogin() {
  return new RequestError(401, 'invalid_credentials', 'The email or password does not match.');
}

function invalidRecovery() {
  return new RequestError(401, 'invalid_recovery', 'The email or recovery code does not match.');
}

async function registerLocalAccount(db, email, password, pepper, now) {
  const id = crypto.randomUUID();
  const [credentials, session] = await Promise.all([newCredentials(password, pepper), newLocalSession(now)]);
  const [inserted, linked] = await db.batch([
    db.prepare(
      'INSERT INTO local_accounts (id, email, password_salt, password_hash, password_scheme, password_iterations, recovery_hash) ' +
      'VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT(email) DO NOTHING',
    ).bind(id, email, credentials.salt, credentials.hash, AUTH_PASSWORD_SCHEME, AUTH_PASSWORD_ITERATIONS, credentials.recoveryHash),
    sessionInsert(db, id, 1, session),
  ]);
  if (!inserted.meta.changes || !linked.meta.changes) {
    throw new RequestError(409, 'registration_unavailable', 'Unable to create the account. Try signing in or using another email.');
  }
  return json({ signedIn: true, recoveryCode: credentials.recoveryCode }, 201, { 'Set-Cookie': authSessionCookie(session.token, AUTH_SESSION_SECONDS) });
}

async function loginLocalAccount(db, email, password, pepper, now) {
  const account = await db.prepare(
    'SELECT id, password_salt, password_hash, password_scheme, password_iterations, credential_version FROM local_accounts WHERE email = ?',
  ).bind(email).first();
  const compatible = account?.password_scheme === AUTH_PASSWORD_SCHEME &&
    Number.isInteger(account.password_iterations) && account.password_iterations > 0 &&
    account.password_iterations <= AUTH_PASSWORD_ITERATIONS;
  const hash = await passwordDigest(
    password,
    compatible ? account.password_salt : '0'.repeat(32),
    compatible ? account.password_iterations : AUTH_PASSWORD_ITERATIONS,
    pepper,
  );
  const matches = equalDigests(hash, compatible ? account.password_hash : '0'.repeat(64));
  if (!matches || !compatible) throw invalidLogin();
  const session = await newLocalSession(now);
  const inserted = await sessionInsert(db, account.id, account.credential_version, session).run();
  if (!inserted.meta.changes) throw invalidLogin();
  return json({ signedIn: true }, 200, { 'Set-Cookie': authSessionCookie(session.token, AUTH_SESSION_SECONDS) });
}

async function resetLocalAccount(db, email, password, recoveryCode, pepper, now) {
  const code = typeof recoveryCode === 'string' && recoveryCode.length <= 80
    ? recoveryCode.replace(/[\s-]/g, '').toLowerCase()
    : '';
  if (!/^[a-f0-9]{32}$/.test(code)) throw invalidRecovery();
  const [recoveryHash, account] = await Promise.all([
    authDigest(code),
    db.prepare('SELECT id, recovery_hash, credential_version FROM local_accounts WHERE email = ?').bind(email).first(),
  ]);
  const matches = equalDigests(recoveryHash, account?.recovery_hash ?? '0'.repeat(64));
  if (!account || !matches) throw invalidRecovery();
  const [credentials, session] = await Promise.all([newCredentials(password, pepper), newLocalSession(now)]);
  const [changed] = await db.batch([
    db.prepare(
      'UPDATE local_accounts SET password_salt = ?, password_hash = ?, password_scheme = ?, password_iterations = ?, ' +
      'recovery_hash = ?, credential_version = credential_version + 1 WHERE id = ? AND recovery_hash = ? AND credential_version = ?',
    ).bind(credentials.salt, credentials.hash, AUTH_PASSWORD_SCHEME, AUTH_PASSWORD_ITERATIONS, credentials.recoveryHash,
      account.id, recoveryHash, account.credential_version),
    db.prepare(
      'DELETE FROM local_sessions WHERE account_id = ? AND credential_version <= ? AND ' +
      'EXISTS (SELECT 1 FROM local_accounts WHERE id = ? AND recovery_hash = ?)',
    ).bind(account.id, account.credential_version, account.id, credentials.recoveryHash),
    db.prepare(
      'INSERT INTO local_sessions (token_hash, account_id, credential_version, expires_at) ' +
      'SELECT ?, id, credential_version, ? FROM local_accounts WHERE id = ? AND recovery_hash = ?',
    ).bind(session.hash, session.expiresAt, account.id, credentials.recoveryHash),
  ]);
  if (!changed.meta.changes) throw invalidRecovery();
  return json({ signedIn: true, recoveryCode: credentials.recoveryCode }, 200, { 'Set-Cookie': authSessionCookie(session.token, AUTH_SESSION_SECONDS) });
}

async function localAuthRequest(request, url, env) {
  if (!AUTH_PATHS.has(url.pathname)) throw new RequestError(404, 'not_found', 'This page was not found.');
  if (request.method !== 'POST') {
    throw new RequestError(405, 'method_not_allowed', 'Use POST for this action.', { Allow: 'POST' });
  }
  requireSameOrigin(request, url);
  const db = env.DB;
  if (!db) throw new RequestError(503, 'auth_unavailable', 'Email sign-in is temporarily unavailable.');
  const action = url.pathname.slice('/api/auth/'.length);
  if (action === 'logout') {
    const token = sessionToken(request);
    if (token) await db.prepare('DELETE FROM local_sessions WHERE token_hash = ?').bind(await authDigest(token)).run();
    return json({ signedIn: false }, 200, { 'Set-Cookie': authSessionCookie('', 0) });
  }
  const input = await readJson(request, 4096);
  const email = authEmail(input.email);
  const password = authPassword(input.password);
  const pepper = await authPepper(env);
  const now = Math.floor(Date.now() / 1000);
  await authRateLimit(request, db, action, email, pepper, now);
  if (action === 'register') return registerLocalAccount(db, email, password, pepper, now);
  if (action === 'reset') return resetLocalAccount(db, email, password, input.recoveryCode, pepper, now);
  return loginLocalAccount(db, email, password, pepper, now);
}

function field(value, name, limit, required = true) {
  const result = typeof value === 'string' ? value.trim() : '';
  if ((!result && required) || result.length > limit) {
    throw new RequestError(400, 'invalid_input', `Enter a valid ${name} (${limit} characters or fewer).`);
  }
  return result;
}

function photograph(value) {
  const invalid = () => new RequestError(400, 'invalid_photo', 'Choose a valid JPEG cat photo.');
  if (typeof value !== 'string' || !value.startsWith(JPEG_PREFIX)) throw invalid();
  if (value.length > MAX_IMAGE_LENGTH) throw new RequestError(413, 'photo_too_large', 'Choose a smaller photo.');

  let bytes;
  try {
    bytes = atob(value.slice(JPEG_PREFIX.length));
  } catch {
    throw invalid();
  }
  if (!bytes.startsWith('\xff\xd8\xff') || !bytes.endsWith('\xff\xd9')) throw invalid();

  // Drop optional application and comment segments such as Exif and GPS metadata.
  const kept = [bytes.slice(0, 2)];
  let start = 2;
  while (start + 3 < bytes.length) {
    if (bytes.charCodeAt(start) !== 0xff) throw invalid();
    let markerPosition = start + 1;
    while (bytes.charCodeAt(markerPosition) === 0xff) markerPosition++;
    const marker = bytes.charCodeAt(markerPosition);
    const size = bytes.charCodeAt(markerPosition + 1) * 256 + bytes.charCodeAt(markerPosition + 2);
    const next = markerPosition + 1 + size;
    if (!Number.isInteger(next) || size < 2 || next > bytes.length - 2) throw invalid();
    if (marker === 0xda) {
      kept.push(bytes.slice(start));
      return btoa(kept.join(''));
    }
    if (!(marker >= 0xe0 && marker <= 0xef) && marker !== 0xfe) kept.push(bytes.slice(start, next));
    start = next;
  }
  throw invalid();
}

function observedDate(input) {
  const malaysiaTime = new Date(Date.now() + 8 * 60 * 60 * 1000);
  const today = malaysiaTime.toISOString().slice(0, 10);
  if (input == null || input === '') return today;
  if (typeof input === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input)) {
    const date = new Date(`${input}T00:00:00Z`);
    if (Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === input && input <= today) return input;
  }
  throw new RequestError(400, 'invalid_date', 'Enter a valid sighting date.');
}

function formatSighting(row) {
  return { ...row, createdAt: new Date(row.createdAt * 1000).toISOString(), image: `/api/sightings/${row.id}/photo` };
}

async function listSightings(statement) {
  const { results } = await statement.all();
  return results.map(formatSighting);
}

async function createSighting(request, db, account) {
  const input = await readJson(request);
  const sighting = {
    id: crypto.randomUUID(),
    name: field(input.name, 'cat name', 60),
    category: input.category,
    city: field(input.city, 'city', 80),
    location: field(input.location, 'general location', 120),
    note: field(input.note, 'note', 500, false),
    observed: observedDate(input.observed),
    status: 'pending',
    ageMonths: input.ageMonths ?? null,
    gender: input.gender ?? 'unknown',
    createdAt: Math.floor(Date.now() / 1000),
  };
  if (!CATEGORIES.has(sighting.category)) throw new RequestError(400, 'invalid_category', 'Select a cat category.');
  if (sighting.ageMonths !== null && (!Number.isInteger(sighting.ageMonths) || sighting.ageMonths < 0 || sighting.ageMonths > 480)) {
    throw new RequestError(400, 'invalid_age', 'Enter an age between 0 and 480 months.');
  }
  if (!GENDERS.has(sighting.gender)) throw new RequestError(400, 'invalid_gender', 'Choose female, male, or unknown.');
  if (!Number.isFinite(input.lat) || !Number.isFinite(input.lng) || input.lat < 0.5 || input.lat > 8 || input.lng < 98 || input.lng > 120) {
    throw new RequestError(400, 'invalid_location', 'Choose an approximate location in Malaysia.');
  }
  sighting.lat = Number(input.lat.toFixed(2));
  sighting.lng = Number(input.lng.toFixed(2));
  const photo = photograph(input.image);
  await db.prepare(`INSERT INTO sightings (id, account_id, name, category, city, location, lat, lng, note, observed, photo, age_months, gender, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`).bind(
    sighting.id, account.id, sighting.name, sighting.category, sighting.city, sighting.location,
    sighting.lat, sighting.lng, sighting.note, sighting.observed, photo, sighting.ageMonths, sighting.gender, sighting.createdAt,
  ).run();
  return json({ sighting: formatSighting(sighting) }, 201);
}

async function servePhoto(statement, account) {
  const row = await statement.first();
  if (!row || (row.status !== 'approved' && row.account_id !== account.id && !account.moderator && !account.platformModerator)) {
    return json({ error: 'not_found', message: 'Photo unavailable.' }, 404);
  }
  return new Response(Uint8Array.from(atob(row.photo), (byte) => byte.charCodeAt(0)), {
    headers: {
      'Content-Type': 'image/jpeg',
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}

function galleryImage(catId, photoId) {
  return '/api/cats/' + catId + '/photos/' + photoId + '/image';
}

function formatGalleryPhoto(row, account) {
  const photo = {
    id: row.id,
    catId: row.cat_id,
    image: galleryImage(row.cat_id, row.id),
    createdAt: new Date(row.created_at).toISOString(),
    status: row.shared ? row.status : 'private',
    shareable: Boolean(row.shared && row.status === 'approved'),
    mine: row.account_id === account?.id,
    likeCount: row.like_count ?? 0,
    liked: Boolean(row.liked),
  };
  if (row.caption) photo.caption = row.caption;
  return photo;
}

function sampleCatProfile(catId) {
  const sample = SAMPLE_CATS.get(catId);
  return sample ? { id: catId, name: sample.name, observed: sample.observed, image: '/' + catId + '.jpg', sample: true } : null;
}

async function requireVisibleCat(db, catId) {
  const sample = sampleCatProfile(catId);
  if (sample) return sample;
  const cat = await db.prepare("SELECT " + SIGHTING_FIELDS + " FROM sightings WHERE id = ? AND status = 'approved'").bind(catId).first();
  if (!cat) throw new RequestError(404, 'cat_not_found', 'This cat profile is unavailable.');
  return formatSighting(cat);
}

function photoRows(db, account, predicate, ...values) {
  return db.prepare(
    'SELECT p.id, p.cat_id, p.account_id, p.caption, p.created_at, p.shared, p.status, ' +
    '(SELECT COUNT(*) FROM photo_likes l WHERE l.cat_id = p.cat_id AND l.photo_id = p.id) AS like_count, ' +
    'EXISTS(SELECT 1 FROM photo_likes l WHERE l.cat_id = p.cat_id AND l.photo_id = p.id AND l.account_id = ?) AS liked ' +
    'FROM cat_photos p WHERE ' + predicate,
  ).bind(account.id ?? null, ...values);
}

async function photoEngagement(db, account, catId, photoId) {
  const result = await db.prepare(
    'SELECT COUNT(*) AS count, MAX(CASE WHEN account_id = ? THEN 1 ELSE 0 END) AS liked FROM photo_likes WHERE cat_id = ? AND photo_id = ?',
  ).bind(account.id ?? null, catId, photoId).first();
  return { likeCount: result.count, liked: Boolean(result.liked) };
}

async function originalPhoto(db, account, cat) {
  const engagement = await photoEngagement(db, account, cat.id, 'original');
  return {
    id: 'original',
    catId: cat.id,
    image: cat.image,
    createdAt: cat.createdAt ?? new Date(cat.observed).toISOString(),
    status: 'approved',
    shareable: true,
    mine: false,
    ...engagement,
  };
}

async function visiblePhoto(db, account, cat, photoId) {
  if (photoId === 'original') return originalPhoto(db, account, cat);
  const row = await photoRows(db, account, 'p.cat_id = ? AND p.id = ?', cat.id, photoId).first();
  if (!row || (row.account_id !== account.id && !(
    row.shared && (row.status === 'approved' || account.moderator || account.platformModerator)
  ))) throw new RequestError(404, 'photo_not_found', 'This photo is unavailable.');
  return formatGalleryPhoto(row, account);
}

function readGalleryCursor(value) {
  if (value === null) return null;
  const match = value.match(/^([0-9]{1,16})\.([a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12})$/);
  const createdAt = Number(match?.[1]);
  if (!match || !Number.isSafeInteger(createdAt)) throw new RequestError(400, 'invalid_gallery_cursor', 'This photo page is unavailable.');
  return { createdAt, id: match[2] };
}

async function galleryPage(db, account, catId, mine, cursor = null) {
  if (mine && !account.id) return { myPhotos: [], myPhotosCursor: null };
  const scope = mine ? 'p.account_id = ?' : "p.status = 'approved' AND p.shared = 1 AND p.account_id IS NOT ?";
  const keys = [catId, account.id ?? null];
  if (cursor) keys.push(cursor.createdAt, cursor.id);
  const after = cursor ? ' AND (p.created_at, p.id) < (?, ?)' : '';
  const { results } = await photoRows(
    db, account, 'p.cat_id = ? AND ' + scope + after + ' ORDER BY p.created_at DESC, p.id DESC LIMIT ?',
    ...keys, GALLERY_PAGE_SIZE + 1,
  ).all();
  const page = results.slice(0, GALLERY_PAGE_SIZE);
  const last = page.at(-1);
  const next = results.length > GALLERY_PAGE_SIZE ? last.created_at + '.' + last.id : null;
  const photos = page.map((row) => formatGalleryPhoto(row, account));
  return mine ? { myPhotos: photos, myPhotosCursor: next } : { photos, photosCursor: next };
}

async function listGallery(db, account, cat, search) {
  const album = search.get('album');
  const token = search.get('cursor');
  if (album !== null) {
    if (album !== 'mine' && album !== 'community') throw new RequestError(400, 'invalid_gallery_album', 'Choose a valid photo album.');
    const mine = album === 'mine';
    if (mine) requireAccount(account);
    return json(await galleryPage(db, account, cat.id, mine, readGalleryCursor(token)));
  }
  if (token !== null) throw new RequestError(400, 'invalid_gallery_album', 'Choose a valid photo album.');

  const [community, personal, nickname, original] = await Promise.all([
    galleryPage(db, account, cat.id, false),
    galleryPage(db, account, cat.id, true),
    account.id ? db.prepare('SELECT nickname FROM cat_nicknames WHERE account_id = ? AND cat_id = ?').bind(account.id, cat.id).first() : null,
    originalPhoto(db, account, cat),
  ]);
  return json({
    nickname: nickname?.nickname ?? null,
    original,
    ...community,
    ...personal,
  });
}

async function listCollection(db, account, search) {
  requireAccount(account);
  const cursor = readGalleryCursor(search.get('cursor'));
  const sampleIds = [...SAMPLE_CATS.keys()];
  const placeholders = sampleIds.map(() => '?').join(', ');
  const after = cursor ? ' AND (r.latest_at, r.latest_id) < (?, ?)' : '';
  const bindings = [account.id, account.id, ...sampleIds];
  if (cursor) bindings.push(cursor.createdAt, cursor.id);
  const { results } = await db.prepare(
    'WITH ranked AS (' +
      'SELECT cat_id, id AS latest_id, created_at AS latest_at, ' +
        'COUNT(*) OVER (PARTITION BY cat_id) AS photo_count, ' +
        'ROW_NUMBER() OVER (PARTITION BY cat_id ORDER BY created_at DESC, id DESC) AS photo_rank ' +
      'FROM cat_photos WHERE account_id = ?' +
    ') SELECT r.cat_id, r.latest_id, r.latest_at, r.photo_count, n.nickname, s.* FROM ranked r ' +
    "LEFT JOIN (SELECT " + SIGHTING_FIELDS + " FROM sightings WHERE status = 'approved') s ON s.id = r.cat_id " +
    'LEFT JOIN cat_nicknames n ON n.account_id = ? AND n.cat_id = r.cat_id ' +
    'WHERE r.photo_rank = 1 AND (s.id IS NOT NULL OR r.cat_id IN (' + placeholders + '))' + after +
    ' ORDER BY r.latest_at DESC, r.latest_id DESC LIMIT ?',
  ).bind(...bindings, GALLERY_PAGE_SIZE + 1).all();
  const page = results.slice(0, GALLERY_PAGE_SIZE);
  const cats = page.map(({ cat_id, latest_id, latest_at, photo_count, nickname, ...sighting }) => ({
    catId: cat_id,
    cat: sampleCatProfile(cat_id) ?? formatSighting(sighting),
    nickname: nickname ?? null,
    photoCount: photo_count,
    latestPhoto: { id: latest_id, image: galleryImage(cat_id, latest_id), createdAt: new Date(latest_at).toISOString() },
  }));
  const last = page.at(-1);
  return json({ cats, cursor: results.length > GALLERY_PAGE_SIZE ? last.latest_at + '.' + last.latest_id : null });
}

async function saveNickname(request, db, account, catId) {
  const { nickname } = await readJson(request, 1024);
  if (nickname !== null && typeof nickname !== 'string') {
    throw new RequestError(400, 'invalid_nickname', 'Enter a nickname or clear the field.');
  }
  const value = field(nickname, 'nickname', 40, false);
  if (value) {
    await db.prepare(
      'INSERT INTO cat_nicknames (account_id, cat_id, nickname) VALUES (?, ?, ?) ' +
      'ON CONFLICT(account_id, cat_id) DO UPDATE SET nickname = excluded.nickname',
    ).bind(account.id, catId, value).run();
  } else {
    await db.prepare('DELETE FROM cat_nicknames WHERE account_id = ? AND cat_id = ?').bind(account.id, catId).run();
  }
  return json({ nickname: value || null });
}

async function transferredCapture(db, account, catId, requestId) {
  const row = await photoRows(db, account, 'p.account_id = ? AND p.client_request_id = ?', account.id, requestId).first();
  if (!row) return null;
  if (row.cat_id !== catId) throw new RequestError(409, 'capture_conflict', 'This capture was already saved to another cat.');
  return json({ photo: formatGalleryPhoto(row, account) });
}

async function createGalleryPhoto(request, db, account, catId) {
  const input = await readJson(request);
  if (input.share !== undefined && typeof input.share !== 'boolean') {
    throw new RequestError(400, 'invalid_share_setting', 'Choose whether to share this photo.');
  }
  if (input.clientRequestId !== undefined && (typeof input.clientRequestId !== 'string' ||
      !/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i.test(input.clientRequestId))) {
    throw new RequestError(400, 'invalid_capture_id', 'Capture the photo again and retry.');
  }
  const requestId = input.clientRequestId?.toLowerCase() ?? null;
  if (requestId) {
    const prior = await transferredCapture(db, account, catId, requestId);
    if (prior) return prior;
  }
  const row = {
    id: crypto.randomUUID(),
    cat_id: catId,
    account_id: account.id,
    caption: field(input.caption, 'caption', 160, false),
    shared: input.share === false ? 0 : 1,
    status: 'pending',
    created_at: Date.now(),
  };
  const image = photograph(input.image);
  const { meta } = await db.prepare(
    'INSERT INTO cat_photos (id, cat_id, account_id, caption, photo, created_at, shared, client_request_id) ' +
    'VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(account_id, client_request_id) DO NOTHING',
  ).bind(row.id, catId, account.id, row.caption, image, row.created_at, row.shared, requestId).run();
  if (!meta.changes && requestId) {
    const prior = await transferredCapture(db, account, catId, requestId);
    if (prior) return prior;
    throw new RequestError(409, 'capture_conflict', 'This capture could not be saved. Retry the request.');
  }
  return json({ photo: formatGalleryPhoto(row, account) }, 201);
}

async function shareGalleryPhoto(db, account, cat, photoId) {
  const photo = await visiblePhoto(db, account, cat, photoId);
  if (!photo.mine) throw new RequestError(404, 'photo_not_found', 'This photo is unavailable.');
  if (photo.status === 'private') {
    await db.prepare('UPDATE cat_photos SET shared = 1 WHERE id = ? AND cat_id = ? AND account_id = ? AND shared = 0')
      .bind(photoId, cat.id, account.id).run();
  }
  return json({ photo: await visiblePhoto(db, account, cat, photoId) });
}

async function setPhotoLike(request, db, account, catId, photoId) {
  const { liked } = await readJson(request, 1024);
  if (typeof liked !== 'boolean') throw new RequestError(400, 'invalid_like', 'Choose whether to like this photo.');
  const statement = liked
    ? 'INSERT INTO photo_likes (cat_id, photo_id, account_id) VALUES (?, ?, ?) ON CONFLICT(cat_id, photo_id, account_id) DO NOTHING'
    : 'DELETE FROM photo_likes WHERE cat_id = ? AND photo_id = ? AND account_id = ?';
  await db.prepare(statement).bind(catId, photoId, account.id).run();
  return json(await photoEngagement(db, account, catId, photoId));
}

function formatPhotoComment(row, account) {
  return {
    id: row.id,
    text: row.body,
    createdAt: new Date(row.created_at).toISOString(),
    status: row.status,
    mine: row.account_id === account.id,
  };
}

async function listComments(db, account, catId, photoId) {
  const { results } = await db.prepare(
    "SELECT id, account_id, body, created_at, status FROM photo_comments WHERE cat_id = ? AND photo_id = ? " +
    "AND (status = 'approved' OR account_id = ?) ORDER BY created_at DESC, id DESC LIMIT 100",
  ).bind(catId, photoId, account.id ?? null).all();
  return results.map((row) => formatPhotoComment(row, account));
}

async function addPhotoComment(request, db, account, catId, photoId) {
  const { text } = await readJson(request, 4096);
  const row = {
    id: crypto.randomUUID(),
    account_id: account.id,
    body: field(text, 'comment', 500),
    created_at: Date.now(),
    status: 'pending',
  };
  const { meta } = await db.prepare(
    'INSERT INTO photo_comments (id, cat_id, photo_id, account_id, body, created_at) SELECT ?, ?, ?, ?, ?, ? ' +
    'WHERE (SELECT COUNT(*) FROM photo_comments WHERE account_id = ? AND created_at > ?) < 8',
  ).bind(row.id, catId, photoId, account.id, row.body, row.created_at,
    account.id, row.created_at - 900_000).run();
  if (!meta.changes) {
    throw new RequestError(429, 'comment_rate_limited', 'Too many comments. Try again later.', { 'Retry-After': '900' });
  }
  return json({ comment: formatPhotoComment(row, account) }, 201);
}

async function galleryRequest(request, url, db, account, catId, { photoId, action, nickname }) {
  const allowed = nickname || action === 'like' ? ['PUT']
    : action === 'share' || action === 'comments' ? ['POST']
      : photoId ? ['GET'] : ['GET', 'POST'];
  if (!allowed.includes(request.method)) {
    throw new RequestError(405, 'method_not_allowed', 'This action does not support that method.', { Allow: allowed.join(', ') });
  }
  if (request.method !== 'GET') {
    requireAccount(account);
    requireSameOrigin(request, url);
  }
  const cat = await requireVisibleCat(db, catId);
  if (nickname) return saveNickname(request, db, account, catId);
  if (!photoId) return request.method === 'POST' ? createGalleryPhoto(request, db, account, catId) : listGallery(db, account, cat, url.searchParams);
  if (action === 'image') {
    if (photoId === 'original') return new Response(null, { status: 302, headers: { Location: cat.image, 'Cache-Control': 'no-store' } });
    const statement = db.prepare('SELECT account_id, status, photo FROM cat_photos WHERE cat_id = ? AND id = ? AND (shared = 1 OR account_id = ?)')
      .bind(catId, photoId, account.id ?? null);
    return servePhoto(statement, account);
  }
  if (action === 'share') return shareGalleryPhoto(db, account, cat, photoId);
  const photo = await visiblePhoto(db, account, cat, photoId);
  if (!action) {
    const comments = photo.shareable ? await listComments(db, account, catId, photoId) : [];
    return json({ photo, comments, cat });
  }
  if (!photo.shareable) throw new RequestError(404, 'photo_not_found', 'This photo is unavailable.');
  if (action === 'like') return setPhotoLike(request, db, account, catId, photoId);
  return addPhotoComment(request, db, account, catId, photoId);
}

async function updateStatus(db, table, id, status) {
  if (status !== 'approved' && status !== 'rejected') {
    throw new RequestError(400, 'invalid_status', 'Choose approve or reject.');
  }
  const sharedOnly = table === 'cat_photos' ? ' AND shared = 1' : '';
  const { meta } = await db.prepare(`UPDATE ${table} SET status = ? WHERE id = ? AND status = 'pending'${sharedOnly}`).bind(status, id).run();
  if (meta.changes === 0) throw new RequestError(409, 'already_reviewed', 'This submission has already been reviewed or removed.');
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

function reviewForm(path) {
  return `<form method="post" action="${path}">
    <button name="status" value="approved">Approve</button>
    <button name="status" value="rejected">Reject</button>
  </form>`;
}

async function reviewPage(db, account) {
  if (!account.id) return new Response(null, { status: 302, headers: { Location: '/signin-with-chatgpt?return_to=%2Freview' } });
  requireModerator(account);
  const [sightings, photos, comments] = await Promise.all([
    listSightings(db.prepare(`SELECT ${SIGHTING_FIELDS} FROM sightings WHERE status = 'pending' ORDER BY created_at LIMIT 30`)),
    db.prepare(`SELECT p.id, p.cat_id, p.caption, p.created_at, s.name AS cat_name
      FROM cat_photos p LEFT JOIN sightings s ON s.id = p.cat_id
      WHERE p.status = 'pending' AND p.shared = 1 ORDER BY p.created_at LIMIT 30`).all(),
    db.prepare(`SELECT c.id, c.cat_id, c.photo_id, c.body, s.name AS cat_name
      FROM photo_comments c LEFT JOIN sightings s ON s.id = c.cat_id
      WHERE c.status = 'pending' ORDER BY c.created_at LIMIT 30`).all(),
  ]);
  const cards = sightings.map((sighting) => `<article>
    <img src="${sighting.image}" alt="" width="160" height="120">
    <h2>${escapeHtml(sighting.name)}</h2>
    <p>${escapeHtml(sighting.category)} · ${escapeHtml(sighting.location)}, ${escapeHtml(sighting.city)} · ${escapeHtml(sighting.observed)}</p>
    <p>${escapeHtml(sighting.note)}</p>
    ${reviewForm(`/review/${sighting.id}`)}
  </article>`).join('');
  const photoCards = photos.results.map((row) => {
    const cat = SAMPLE_CATS.get(row.cat_id)?.name ?? row.cat_name ?? row.cat_id;
    return `<article>
      <img src="${galleryImage(row.cat_id, row.id)}" alt="" width="160" height="120">
      <h3>${escapeHtml(cat)}</h3>
      <p>${escapeHtml(row.caption)}</p>
      ${reviewForm(`/review/photos/${row.id}`)}
    </article>`;
  }).join('');
  const commentCards = comments.results.map((row) => {
    const cat = SAMPLE_CATS.get(row.cat_id)?.name ?? row.cat_name ?? row.cat_id;
    return `<article>
      <img src="${galleryImage(row.cat_id, row.photo_id)}" alt="" width="160" height="120">
      <h3>${escapeHtml(cat)}</h3>
      <p>${escapeHtml(row.body)}</p>
      ${reviewForm(`/review/comments/${row.id}`)}
    </article>`;
  }).join('');
  return new Response(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Review contributions | ManaMeow</title><style>
    body{font:1rem system-ui,sans-serif;max-width:60rem;padding:1rem;margin:auto;background:#fff8ee;color:#30251b}
    article{padding:1rem;margin:1rem 0;background:white;border-radius:1rem;overflow:auto}
    img{object-fit:cover;float:left;margin:0 1rem .5rem 0;border-radius:.5rem}button{padding:.5rem 1rem;margin-right:.5rem;font:inherit;cursor:pointer}
  </style></head><body><main><p><a href="/">ManaMeow</a></p><h1>Review contributions</h1>
  <section><h2>Sightings</h2>${cards || '<p>There are no pending sightings.</p>'}</section>
  <section><h2>Community photos</h2>${photoCards || '<p>There are no pending community photos.</p>'}</section>
  <section><h2>Photo comments</h2>${commentCards || '<p>There are no pending comments.</p>'}</section>
  </main></body></html>`, {
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store',
      'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; img-src 'self'; form-action 'self'; base-uri 'none'",
    },
  });
}

async function handleApi(request, url, env, account) {
  const { pathname } = url;
  const { method } = request;
  if (pathname === '/api/account' && method === 'GET') {
    return json({
      available: Boolean(env.DB),
      signedIn: Boolean(account.id),
      local: account.local,
      email: account.email ?? null,
      moderator: account.moderator,
      platformModerator: account.platformModerator,
      signInUrl: '/signin-with-chatgpt?return_to=%2F',
      signOutUrl: '/signout-with-chatgpt?return_to=%2F',
    });
  }
  if (!env.DB) throw new RequestError(503, 'storage_unavailable', 'Shared sightings are temporarily unavailable.');

  if (pathname === '/api/collection' && method === 'GET') return listCollection(env.DB, account, url.searchParams);
  const gallery = pathname.match(/^\/api\/cats\/([a-z0-9-]{1,36})\/(?:(nickname)|photos(?:\/(original|[a-f0-9-]{36})(?:\/(image|share|like|comments))?)?)$/);
  if (gallery) {
    const [, catId, nickname, photoId, action] = gallery;
    return galleryRequest(request, url, env.DB, account, catId, { photoId, action, nickname });
  }
  if (pathname === '/api/sightings' && method === 'GET') {
    const sightings = await listSightings(env.DB.prepare(`SELECT ${SIGHTING_FIELDS} FROM sightings WHERE status = 'approved' ORDER BY observed DESC, created_at DESC LIMIT 100`));
    return json({ sightings });
  }
  if (pathname === '/api/sightings' && method === 'POST') {
    requireAccount(account);
    requireSameOrigin(request, url);
    return createSighting(request, env.DB, account);
  }
  if (pathname === '/api/sightings/mine' && method === 'GET') {
    requireAccount(account);
    const sightings = await listSightings(env.DB.prepare(`SELECT ${SIGHTING_FIELDS} FROM sightings WHERE account_id = ? ORDER BY created_at DESC LIMIT 100`).bind(account.id));
    return json({ sightings });
  }
  if (pathname === '/api/sightings/review' && method === 'GET') {
    requireModerator(account);
    const sightings = await listSightings(env.DB.prepare(`SELECT ${SIGHTING_FIELDS} FROM sightings WHERE status = 'pending' ORDER BY created_at LIMIT 100`));
    return json({ sightings });
  }
  const photo = pathname.match(/^\/api\/sightings\/([a-f0-9-]{36})\/photo$/);
  if (photo && method === 'GET') {
    return servePhoto(env.DB.prepare('SELECT account_id, status, photo FROM sightings WHERE id = ?').bind(photo[1]), account);
  }

  const review = pathname.match(/^\/api\/sightings\/review\/([a-f0-9-]{36})$/);
  if (review && method === 'POST') {
    requireModerator(account);
    requireSameOrigin(request, url);
    const { status } = await readJson(request);
    await updateStatus(env.DB, 'sightings', review[1], status);
    return json({ status });
  }
  throw new RequestError(404, 'not_found', 'This page was not found.');
}

function serveEmbeddedAsset(request, url) {
  if (request.method !== 'GET' && request.method !== 'HEAD') return null;
  const path = url.pathname === '/' ? '/index.html' : url.pathname;
  const asset = EMBEDDED_ASSETS[path];
  if (!asset) return null;

  const [type, contents] = asset;
  const body = request.method === 'HEAD'
    ? null
    : Uint8Array.from(atob(contents), (byte) => byte.charCodeAt(0));
  return new Response(body, {
    headers: {
      'Content-Type': type,
      'Cache-Control': 'no-cache',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const authRoute = url.pathname.startsWith('/api/auth/');
    try {
      if (authRoute) return await localAuthRequest(request, url, env);
      if (url.pathname.startsWith('/api/')) {
        const account = await getRequestAccount(request, env);
        return await handleApi(request, url, env, account);
      }
      const account = getAccount(request, env);
      if (url.pathname === '/review' && request.method === 'GET' && env.DB) return await reviewPage(env.DB, account);
      const review = url.pathname.match(/^\/review\/(?:(photos|comments)\/)?([a-f0-9-]{36})$/);
      if (review && request.method === 'POST' && env.DB) {
        requireModerator(account);
        requireSameOrigin(request, url);
        const form = await request.formData();
        const table = { photos: 'cat_photos', comments: 'photo_comments' }[review[1]] ?? 'sightings';
        await updateStatus(env.DB, table, review[2], form.get('status'));
        return Response.redirect(new URL('/review', url), 303);
      }
      const assetResponse = env.ASSETS ? await env.ASSETS.fetch(request) : null;
      if (assetResponse && assetResponse.status !== 404) return assetResponse;
      return serveEmbeddedAsset(request, url) ?? assetResponse ?? new Response('Page not found.', { status: 404 });
    } catch (error) {
      if (error instanceof RequestError) return json({ error: error.code, message: error.message }, error.status, error.headers);
      if (authRoute) console.error('ManaMeow authentication request failed');
      else console.error('ManaMeow request failed', error?.message);
      return json({ error: 'server_error', message: 'ManaMeow could not complete that request. Try again.' }, 500);
    }
  },
};

